def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    count = 3
    if count == 0:
        return None
    average = (v1 + v2 + v3) / count
    return {
        "value": average,
        "trace": {
            "values": [v1, v2, v3],
            "count": count,
            "average": average,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
